const h = document.createElement('div');
h.style.position = 'absolute';
h.style.border = '4px solid #00FFFF';
h.style.zIndex = '9999';
h.style.pointerEvents = 'none';
h.style.boxSizing = 'border-box';
const head = document.querySelector('otto-web-grid-header .header__cell:nth-child(1)');
const col2 = document.querySelector('otto-web-grid-header .header__cell:nth-child(2)');
const lastRowCell = document.querySelector('otto-web-grid-row:last-child otto-web-grid-entity-cell');
if (head && col2 && lastRowCell) {
  const r1 = head.getBoundingClientRect();
  const r2 = col2.getBoundingClientRect();
  const r3 = lastRowCell.getBoundingClientRect();
  h.style.top = (r1.top - 4) + 'px';
  h.style.left = (r1.left - 4) + 'px';
  h.style.width = (r2.right - r1.left + 8) + 'px';
  h.style.height = (r3.bottom - r1.top + 8) + 'px';
  document.body.appendChild(h);
}
